test.config:
indexer
{
	mem_limit = 16M
}

searchd
{

}

source score_independent_source
{
	type = mysql

	sql_query = SELECT id, body, gid FROM score_independent_docs ORDER BY insertion_order
	sql_attr_uint = gid
}

index score_independent_plain
{
	source = score_independent_source
	path = /score_independent_plain
}

index score_independent_configured : score_independent_plain
{
	path = /score_independent_configured
	ranker = none
}

index score_independent_dist
{
	type = distributed
	local = score_independent_plain
}

queries.sphinxql:
/* Exact public numeric IDs, not physical row IDs. */
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 5;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 4,5;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 32;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 33;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_configured WHERE MATCH('alpha') ORDER BY id ASC LIMIT 5;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';

/* The truncated top-K representation must neither consume nor populate qcache. */
SET GLOBAL qcache_max_bytes=16777216;
SET GLOBAL qcache_thresh_msec=0;
SELECT id,weight() FROM score_independent_plain WHERE MATCH('alpha') ORDER BY weight() DESC LIMIT 5;
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 5;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 5;
SHOW META LIKE 'total_found';
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id,weight() FROM score_independent_plain WHERE MATCH('alpha') ORDER BY weight() DESC LIMIT 5;
SET GLOBAL qcache_max_bytes=0;

/* Every shape below must retain its established ranker and omit the marker. */
SELECT id FROM score_independent_plain WHERE MATCH('alpha') LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY weight() DESC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id,weight() FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id,weight()+1 AS scored FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') HAVING weight()>0 ORDER BY id ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') AND gid=1 ORDER BY id ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 2 OPTION ranker=none;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC LIMIT 2 OPTION ranker=bm25a;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('@body alpha') ORDER BY id ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT gid,COUNT(*) FROM score_independent_plain WHERE MATCH('alpha') GROUP BY gid ORDER BY gid ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY gid ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id ASC,gid ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_plain WHERE MATCH('alpha') ORDER BY id DESC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
SELECT id FROM score_independent_dist WHERE MATCH('alpha') ORDER BY id ASC LIMIT 2;
SHOW META LIKE 'auto_rankless';
SHOW META LIKE 'auto_id_topk';
